    trapExamples: [{ question: "1L は 何mL ですか。", wrongAnswer: "100mL", trapExplanation: "1dL＝100mL と ごっちゃに した。", correctAnswer: "1000mL", correctExplanation: "1L＝10dL、1dL＝100mL。だから 1L＝1000mL。" }],
