    trapExamples: [{ question: "1L2dL と 13dL では どちらが 多い？", wrongAnswer: "1L2dL", trapExplanation: "L が ついて いるから 多いと おもった。", correctAnswer: "13dL", correctExplanation: "1L2dL＝12dL。13dL の ほうが 1dL 多い。" }],
