    description: "時こくと 時間の たし算・ひき算の 文章題を とく",
    intro: "「10時20分に はじめて、1時間45分 かかりました。おわった 時こくは？」の ような 問題を とく とき、時間の たし算を 使います。",
    keyPoints: ["時こく ＋ 時間 ＝ 時こく", "時こく − 時間 ＝ 時こく", "ちょうどの 時こくを 目印に 計算"],
    sections: [
      { heading: "1. 時間の 文章題", body: "■ とき方\n10時20分に はじめて、1時間45分 かかる。\n① 10時20分 ＋ 1時間 ＝ **11時20分**\n② 11時20分 ＋ 45分：まず 40分で 12時（11時20分＋40分）、あと 5分 で **12時5分**\n③ **12時5分**に おわる\n\n■ なぜ 分けて 足すの？\n時間は 60分で くり上がるので、まず 時間を 足し、次に 分を ちょうどの 時こくを 目印に 足すと、まちがえません。\n\n★ ここがポイント：**時間 → 分** の 順に 足す。**ちょうど**を 目印に する。", figureId: "u120e2_050_a" },
      { heading: "2. やってみよう", body: "【なにを きかれているかな】10時20分に はじめて、1時間45分 かかりました。おわった 時こくは？\n\n【なぜ この やりかたかな】時こくに 時間を 足すと おわりの 時こくに なるから。\n\n【ステップ1】10時20分＋1時間＝11時20分\n【ステップ2】11時20分＋40分＝12時（ちょうど）\n【ステップ3】12時＋5分＝12時5分\n\n【こたえ】12時5分\n\n【たしかめ】12時5分−1時間45分＝10時20分。もとの 時こくに なった。" },
      { heading: "3. たしかめ（けんざん）の しかた", body: "■ やりかた その1\nひき算で たしかめる。12時5分の 1時間45分 前は、1時間前 11時5分、さらに 45分 前 10時20分。\n\n■ やりかた その2\n数直線に かいて、1時間 と 45分を じゅんに すすめて たしかめる。\n\n★ ここがポイント：**べつの 方法**でも 計算して、答えが 同じに なるか たしかめる。" },
      { heading: "4. よくある まちがい", body: "■ 分を そのまま 足す\n20分＋45分＝65分 と 書いて、そのまま 答える（65分＝1時間5分に くり上げない）。\n\n■ なおしかた\n・60分で 1時間に くり上げる\n・「ちょうど」の 時こくを はさむ\n\n★ ここがポイント：**60分で 1時間**に くり上げる。" },
      { heading: "5. じぶんの ことばで いってみよう", body: "■ ことばに して みよう（アウトプット）\n・今日の ゲームの 開始時刻と かかった 時間から、終わった 時刻を 計算して みよう\n・時間の たし算で「60分で くり上がる」わけを おうちの 人に 説明してみよう\n\n■ おうちの人へ\n日常の 活動の 時こくを 計算して みる 習慣を つけましょう。\n\n★ ここがポイント：**読むだけでなく、声に出して言う・紙に書く**と、しっかり身につきます。まちがえても大丈夫。「どうしてそう思ったの？」と聞いてあげてください。" },
    ],
    trapExamples: [{ question: "10時20分に はじめて、1時間45分 かかりました。おわった 時こくは？", wrongAnswer: "11時65分", trapExplanation: "分の 20＋45＝65 を そのまま かいた。", correctAnswer: "12時5分", correctExplanation: "65分＝1時間5分に くり上げて、11時＋1時間5分＝12時5分。" }],
