    intro: "「3×4＝12」の ×（かける）は、同じ 数が いくつ分 あるかを あらわす きごうです。しきの かき方・読み方を おぼえましょう。",
    keyPoints: ["「1つぶんの 数 × いくつ分」の じゅんで かく", "3×4＝12 と かいて「さん かける よん は じゅうに」と よむ", "答えには 単位（こ・まい）を つける"],
    sections: [
      { heading: "1. かけ算の しき", body: "■ しきの かき方\n1さらに 3こずつ、4さら。\n**3 × 4 ＝ 12**\n・3：1つぶんの 数（かけられる 数）\n・×：かける\n・4：いくつ分（かける 数）\n・12：ぜんぶの 数（答え）\n\n■ 読み方\n「さん かける よん は じゅうに」と よみます。\n\n■ なぜ この じゅんばん？\n「3の 4つ分」と 読んで、「3」を さきに 書き、「いくつ分か」の 4 を あとに 書く きまりです。この きまりに そろえると、まちがいが へります。\n\n★ ここがポイント：**1つぶんの 数 × いくつ分 ＝ ぜんぶ**。", figureId: "u120e2_052_a" },
      { heading: "2. やってみよう", body: "【なにを きかれているかな】1ふくろに あめが 5こ、3ふくろ あります。しきを かいて 答えを 出しましょう。\n\n【なぜ この やりかたかな】きまりの じゅんで 書くと、あとで 読み直しやすいから。\n\n【ステップ1】1つぶんの 数は 5こ\n【ステップ2】いくつ分は 3ふくろ\n【ステップ3】5×3＝5＋5＋5＝15\n\n【こたえ】5×3＝15（15こ）\n\n【たしかめ】5＋5＋5＝15 で 同じ。" },
      { heading: "3. たしかめ（けんざん）の しかた", body: "■ たし算で たしかめる\n5×3 ＝ 5＋5＋5 ＝ 15。しきと 答えが 合うか 見る。\n\n■ 絵で たしかめる\n5こずつ ○を 3つ かいて、ぜんぶ 数える。\n\n★ ここがポイント：しきの **よみかた**が 合うか 声に 出して たしかめる。" },
      { heading: "4. よくある まちがい", body: "■ しきを 5＋3 と かく\n同じ 数が いくつ分 あるのに、たし算の しきに して しまう。\n\n■ なおしかた\n・「同じ 数が いくつ分」と 言って みる\n・「1つぶん」と「いくつ分」を 先に 書き出す\n\n★ ここがポイント：「**1つぶん**」と「**いくつ分**」を 見つける。" },
      { heading: "5. じぶんの ことばで いってみよう", body: "■ ことばに して みよう（アウトプット）\n・5×3 を「5が 3つ分」と 声に 出して 読んでみよう\n・自分で かけ算の おはなしを つくって、しきを かいてみよう\n\n■ おうちの人へ\n「1つぶん」と「いくつ分」を 一緒に 指さして 確かめる 習慣が 大切です。\n\n★ ここがポイント：**読むだけでなく、声に出して言う・紙に書く**と、しっかり身につきます。まちがえても大丈夫。「どうしてそう思ったの？」と聞いてあげてください。" },
    ],
    trapExamples: [{ question: "1ふくろに あめが 5こ、3ふくろ。しきは？", wrongAnswer: "5＋3", trapExplanation: "たし算の しきに して しまった。", correctAnswer: "5×3", correctExplanation: "5が 3つ分 だから 5×3。" }],
