    studyPeriod: '小2',
    order: 40053,
    title: "2の だん",
    description: "2の だんの 九九を となえて、おぼえる",
    intro: "2の だんの 九九を おぼえましょう。九九は 声に 出して となえると、リズムで おぼえられます。2の だんは、足す 数が 2 なので、「2、4、6、8…」と 2ずつ ふえる ことを 意識します。",
    keyPoints: ["2×1 から 2×9 まで となえられる", "2の だんは 2ずつ ふえる", "かける 数が 1 ふえると、答えは かけられる 数だけ ふえる"],
    sections: [
      { heading: "1. 2の だん", body: "■ 2の だんの 九九\n2×1＝2（にいちが に）\n2×2＝4（ににんが し）\n2×3＝6（にさんが ろく）\n2×4＝8（にし が はち）\n2×5＝10（に ご じゅう）\n2×6＝12（にろく じゅうに）\n2×7＝14（にしち じゅうし）\n2×8＝16（に はち じゅうろく）\n2×9＝18（にく じゅうはち）\n\n■ なぜ 2ずつ ふえるの？\n「2×k」は「2が k こ分」の ことです。k が 1 ふえると、2の かたまりが もう 1つ ふえるので、答えは **2だけ ふえます**。2×1＝2 から はじめて、2、4、6、…と 2ずつ ふえて いきます。\n\n■ おぼえる コツ\n2、4、6、8、10…と 2とびに 数える ことから はじめましょう。\n\n★ ここがポイント：**2の だん は 2ずつ ふえる**。声に 出して、リズムで おぼえる。", figureId: "u120e2_053_a" },
      { heading: "2. やってみよう", body: "【なにを きかれているかな】2×6 は いくつ？\n\n【なぜ この やりかたかな】「2の かたまりが 6こ分」だから、2を 6回 たしても 同じ 答えに なる。\n\n【ステップ1】2の だんを はじめから となえる：2、4、6、8、10、12\n【ステップ2】6ばんめの 数が 答え\n\n【こたえ】12\n\n【たしかめ】2＋2＋2＋2＋2＋2＝12 で たし算でも 同じ。" },
      { heading: "3. たしかめ（けんざん）の しかた", body: "■ たし算で たしかめる\n2×6 は 2を 6回 たした 数。2＋2＋2＋2＋2＋2＝12。九九の 答えと 同じに なれば OK。\n\n■ 前後の 九九で たしかめる\n2×5＝10、これに 2 を たすと 12。2×6 と 同じ。\n\n★ ここがポイント：**となりの 九九に 2を たす（ひく）**と、たしかめられる。" },
      { heading: "4. よくある まちがい", body: "■ 3×2 と 2×3 を ごっちゃにする\n\n■ なおしかた\n・九九を 1の だんから じゅんに となえて たしかめる\n・たし算（2を ふやす）で たしかめる\n\n★ ここがポイント：まよったら **2ずつ たして** たしかめる。" },
      { heading: "5. じぶんの ことばで いってみよう", body: "■ ことばに して みよう（アウトプット）\n・2の だんを 声に 出して となえてみよう\n・2×6 の 答えが なぜ 12 か、たし算で おうちの 人に 説明してみよう\n\n■ おうちの人へ\n毎日 1回ずつ 九九を となえる 習慣を つけましょう。おふろや 歩きながらも いい 練習です。\n\n★ ここがポイント：**読むだけでなく、声に出して言う・紙に書く**と、しっかり身につきます。まちがえても大丈夫。「どうしてそう思ったの？」と聞いてあげてください。" },
    ],
    trapExamples: [{ question: "2×6 は いくつ？", wrongAnswer: "14", trapExplanation: "2×5 の 答えに 2を 2回 たして しまった。", correctAnswer: "12", correctExplanation: "2×5＝10、2を 1回 たして 12。" }],
