    intro: "5の だんの 九九を おぼえましょう。九九は 声に 出して となえると、リズムで おぼえられます。5の だんの 答えは、一の くらいが かならず 5か 0 に なります。",
    keyPoints: ["5×1 から 5×9 まで となえられる", "5の だんは 5ずつ ふえる", "かける 数が 1 ふえると、答えは かけられる 数だけ ふえる"],
    sections: [
      { heading: "1. 5の だん", body: "■ 5の だんの 九九\n5×1＝5（ごいちが ご）\n5×2＝10（ご に じゅう）\n5×3＝15（ご さん じゅうご）\n5×4＝20（ご し にじゅう）\n5×5＝25（ご ご にじゅうご）\n5×6＝30（ご ろく さんじゅう）\n5×7＝35（ご しち さんじゅうご）\n5×8＝40（ご は しじゅう）\n5×9＝45（ご く しじゅうご）\n\n■ なぜ 5ずつ ふえるの？\n「5×k」は「5が k こ分」の ことです。k が 1 ふえると、5の かたまりが もう 1つ ふえるので、答えは **5だけ ふえます**。5×1＝5 から はじめて、5、10、15、…と 5ずつ ふえて いきます。\n\n■ おぼえる コツ\n5の だんは 一の くらいが 5、0、5、0…と くりかえす ので、おぼえやすい だんです。\n\n★ ここがポイント：**5の だん は 5ずつ ふえる**。声に 出して、リズムで おぼえる。", figureId: "u120e2_054_a" },
      { heading: "2. やってみよう", body: "【なにを きかれているかな】5×6 は いくつ？\n\n【なぜ この やりかたかな】「5の かたまりが 6こ分」だから、5を 6回 たしても 同じ 答えに なる。\n\n【ステップ1】5の だんを はじめから となえる：5、10、15、20、25、30\n【ステップ2】6ばんめの 数が 答え\n\n【こたえ】30\n\n【たしかめ】5＋5＋5＋5＋5＋5＝30 で たし算でも 同じ。" },
      { heading: "3. たしかめ（けんざん）の しかた", body: "■ たし算で たしかめる\n5×6 は 5を 6回 たした 数。5＋5＋5＋5＋5＋5＝30。九九の 答えと 同じに なれば OK。\n\n■ 前後の 九九で たしかめる\n5×5＝25、これに 5 を たすと 30。5×6 と 同じ。\n\n★ ここがポイント：**となりの 九九に 5を たす（ひく）**と、たしかめられる。" },
      { heading: "4. よくある まちがい", body: "■ 5の だんで 答えの 一の くらいを まちがえる\n\n■ なおしかた\n・九九を 1の だんから じゅんに となえて たしかめる\n・たし算（5を ふやす）で たしかめる\n\n★ ここがポイント：まよったら **5ずつ たして** たしかめる。" },
      { heading: "5. じぶんの ことばで いってみよう", body: "■ ことばに して みよう（アウトプット）\n・5の だんを 声に 出して となえてみよう\n・5×6 の 答えが なぜ 30 か、たし算で おうちの 人に 説明してみよう\n\n■ おうちの人へ\n毎日 1回ずつ 九九を となえる 習慣を つけましょう。おふろや 歩きながらも いい 練習です。\n\n★ ここがポイント：**読むだけでなく、声に出して言う・紙に書く**と、しっかり身につきます。まちがえても大丈夫。「どうしてそう思ったの？」と聞いてあげてください。" },
    ],
    trapExamples: [{ question: "5×6 は いくつ？", wrongAnswer: "35", trapExplanation: "5×5 の 答えに 5を 2回 たして しまった。", correctAnswer: "30", correctExplanation: "5×5＝25、5を 1回 たして 30。" }],
