    intro: "九九の 表は、1の だんから 9の だんまでの 答えを 一まいに まとめた 表です。たてと よこの 数を 見て、交わる ところが 答えです。",
    keyPoints: ["たてと よこの 数が 交わる ところが 答え", "同じ 答えが ななめに ならぶ（入れかえ）", "表を 見ると きまりが 見つかる"],
    sections: [
      { heading: "1. 九九の 表を 見る", body: "■ 表の 見かた\nよこに かける 数、たてに かけられる 数が ならんでいます。\n・たて 6、よこ 7 の 交わる ところ → **42**（6×7＝42）\n\n■ 同じ 答えが ならぶ\n6×7＝42 と 7×6＝42 の ように、表の 左上から 右下の ななめを さかいに、同じ 答えが ならびます。これが「入れかえても 同じ」ことです。\n\n■ なぜ 表が べんりなの？\n九九全体の ようすが 一目で 見え、きまりを 見つけやすく、わすれた 九九も すぐ 見つかるからです。\n\n★ ここがポイント：**たて × よこ の 交わる ところ**が 答え。", figureId: "u120e2_064_a" },
      { heading: "2. やってみよう", body: "【なにを きかれているかな】九九の 表で、たて 6、よこ 7 の 交わる ところの 数は？\n\n【なぜ この やりかたかな】たてと よこの 数を そろえて 見ると、答えが 見つかるから。\n\n【ステップ1】よこの 7 の 列を 見る\n【ステップ2】たての 6 の 行を 見る\n【ステップ3】交わる ところの 数を 読む\n\n【こたえ】42\n\n【たしかめ】6×7＝6×6＋6＝36＋6＝42 と たしかめられる。" },
      { heading: "3. たしかめ（けんざん）の しかた", body: "■ 入れかえて たしかめる\n7×6 の 場所も 見て、同じ 42 か たしかめる。\n\n■ 九九を となえて たしかめる\n6の だんを 声に 出す：6、12、18、24、30、36、42。7ばんめが 42。\n\n★ ここがポイント：**入れかえた 場所**の 答えと くらべる。" },
      { heading: "4. よくある まちがい", body: "■ たての 数と よこの 数を とりちがえる\n6×7 の はずが 7×6 の 場所を 読んで しまう（答えは 同じ だが）。\n\n■ なおしかた\n・まず たて、次に よこ の じゅんで 指を 動かす\n\n★ ここがポイント：**たて → よこ** の じゅんで 見る。" },
      { heading: "5. じぶんの ことばで いってみよう", body: "■ ことばに して みよう（アウトプット）\n・九九の 表で、答えが 24 に なる ところを すべて さがしてみよう\n・九九の 表を 見て、見つけた きまりを おうちの 人に 説明してみよう\n\n■ おうちの人へ\n九九の 表を かべに はって、毎日 ちがう きまりを 一つずつ 見つける 遊びを しましょう。\n\n★ ここがポイント：**読むだけでなく、声に出して言う・紙に書く**と、しっかり身につきます。まちがえても大丈夫。「どうしてそう思ったの？」と聞いてあげてください。" },
    ],
    trapExamples: [{ question: "九九の 表で たて 6、よこ 7 の 交わる ところの 数は？", wrongAnswer: "13", trapExplanation: "6＋7 を して しまった。", correctAnswer: "42", correctExplanation: "交わる ところは かけ算の 答え。6×7＝42。" }],
