    order: 40065,
    title: "九九の パターンを さがそう",
    description: "九九の 答えに かくれて いる きまりを 見つける",
    intro: "九九の 答えには、おもしろい きまりが たくさん かくれて います。9の だんの 答えは、十の くらいと 一の くらいを たすと 9 に なります。5の だんは 一の くらいが 5か 0 です。",
    keyPoints: ["9の だん：十の くらい ＋ 一の くらい ＝ 9", "5の だん：一の くらいは 5か 0", "2の だんの 答えは ぜんぶ 2ずつ ふえる"],
    sections: [
      { heading: "1. 九九の パターンを さがそう", body: "■ きまり①：9の だん\n9、18、27、36、45、54、63、72、81。\n・十の くらいは 1ずつ ふえる（0→1→2→…→8）\n・一の くらいは 1ずつ へる（9→8→7→…→1）\n・十の くらい ＋ 一の くらい ＝ **9**（18→1＋8＝9）\n\n■ きまり②：5の だん\n5、10、15、20、25、30、35、40、45。一の くらいが **5・0・5・0** と くりかえす。\n\n■ きまり③：2の だん\n2、4、6、8、10、…、18。一の くらいが **2・4・6・8・0** と くりかえす。2つずつ 分けられる 数ばかり です。\n\n■ なぜ そうなるの？\n9の だんは 9ずつ ふえます。9 は 10−1 なので、十の くらいが 1 ふえて、一の くらいが 1 へる からです。\n\n★ ここがポイント：9の だんは **十の くらい ＋ 一の くらい ＝ 9**。", figureId: "u120e2_065_a" },
      { heading: "2. やってみよう", body: "【なにを きかれているかな】9×7 の 答えが 63 か、十の くらいと 一の くらいで たしかめましょう。\n\n【なぜ この やりかたかな】9の だんの きまりを 使うと、答えが 合って いるか すぐ わかるから。\n\n【ステップ1】63 の 十の くらいは 6、一の くらいは 3\n【ステップ2】6＋3＝9\n【ステップ3】9 に なった\n\n【こたえ】63 は 合っている\n\n【たしかめ】9×7＝9×6＋9＝54＋9＝63。" },
      { heading: "3. たしかめ（けんざん）の しかた", body: "■ きまりで たしかめる\n9×7＝63。6＋3＝9 なので 合っている。もし 54（9×6）なら 5＋4＝9 で、これも きまりを 満たす。\n\n■ たし算で たしかめる\n9を 7回 たす：9＋9＋9＋9＋9＋9＋9＝63。\n\n★ ここがポイント：**きまり**と **たし算**の 両方で たしかめる。" },
      { heading: "4. よくある まちがい", body: "■ きまりだけ で 答えを きめる\n十の くらい ＋ 一の くらい ＝ 9 に なる 数は 18、27、36、45、…と たくさん あるので、きまりだけでは 答えが きまらない。\n\n■ なおしかた\n・きまりは たしかめに 使う\n・答えは 九九で もとめる\n\n★ ここがポイント：きまりは **たしかめ**に 使う。" },
      { heading: "5. じぶんの ことばで いってみよう", body: "■ ことばに して みよう（アウトプット）\n・九九の 表から、自分で 見つけた きまりを 1つ 言ってみよう\n・9の だんの きまりを おうちの 人に 説明してみよう\n\n■ おうちの人へ\n九九の きまりを 見つける 遊びは、考える 力を 育てます。一緒に さがして みましょう。\n\n★ ここがポイント：**読むだけでなく、声に出して言う・紙に書く**と、しっかり身につきます。まちがえても大丈夫。「どうしてそう思ったの？」と聞いてあげてください。" },
    ],
    trapExamples: [{ question: "9×7 の 答えは 63。十の くらい ＋ 一の くらいは？", wrongAnswer: "63", trapExplanation: "答えそのものを 書いた。", correctAnswer: "9（6＋3）", correctExplanation: "十の くらいの 6 と 一の くらいの 3 を たす。" }],
