    keyPoints: ["4本の 直線で かこまれた 形", "辺が 4つ、ちょう点が 4つ", "長方形・正方形も 四角形の なかま"],
    sections: [
      { heading: "1. 四角形とは", body: "■ 四角形って なに？\n**4本の 直線**で かこまれた 形が「四角形」です。\n・辺は **4つ**、ちょう点は **4つ**\n\n■ 四角形の なかま\n・長方形（4つの かどが 直角）\n・正方形（4つの かどが 直角で、4つの 辺が 同じ 長さ）\n・ひし形・台形 など（もっと 上の 学年で 学びます）\n\n■ なぜ 4つ 数えるの？\n辺の 数が その 形の 名前に なって いるからです。3本なら 三角形、4本なら 四角形です。\n\n★ ここがポイント：**4本の 直線**で かこまれた 形。辺も ちょう点も **4つ**。", figureId: "u120e2_074_a" },
      { heading: "2. やってみよう", body: "【なにを きかれているかな】四角形の 辺と ちょう点は それぞれ いくつ？\n\n【なぜ この やりかたかな】四角形は 4本の 直線で かこむ 形だから。\n\n【ステップ1】4本の 直線で かこむ\n【ステップ2】辺を 数える：4つ\n【ステップ3】かどを 数える：4つ\n\n【こたえ】辺 4つ、ちょう点 4つ\n\n【たしかめ】ノートの ふちを なぞって 数える。" },
      { heading: "3. たしかめ（けんざん）の しかた", body: "■ やりかた その1\n本の 表紙を 指で なぞって、辺と かどを 数える。\n\n■ やりかた その2\n紙を 四角に 切って、辺と ちょう点に しるしを つけて 数える。\n\n★ ここがポイント：**べつの 方法**でも たしかめて、同じに なるか 見る。" },
      { heading: "4. よくある まちがい", body: "■ ■ 辺の 数と ちょう点の 数が ちがうと おもう\n三角形では どちらも 3つ だったが、四角形で ちがうと かんちがいする。\n\n■ なおしかた\n・三角形や 四角形では 辺の 数と ちょう点の 数は いつも 同じ\n・指で 1つずつ なぞって 数える\n\n★ ここがポイント：まちがえやすい ところを **先に 知って**おく。" },
      { heading: "5. じぶんの ことばで いってみよう", body: "■ ことばに して みよう（アウトプット）\n・身の まわりで 四角形の ものを 3つ さがしてみよう\n・四角形の 辺と ちょう点の 数を おうちの 人に 説明してみよう\n\n■ おうちの人へ\nドアや まどなど、いろいろな 四角形を 家の 中から さがして みましょう。\n\n★ ここがポイント：**読むだけでなく、声に出して言う・紙に書く**と、しっかり身につきます。まちがえても大丈夫。「どうしてそう思ったの？」と聞いてあげてください。" },
    ],
    trapExamples: [{ question: "四角形の ちょう点は いくつ？", wrongAnswer: "3つ", trapExplanation: "三角形と まちがえた。", correctAnswer: "4つ", correctExplanation: "四角形は 4本の 直線で かこまれた 形。ちょう点も 4つ。" }],
