    keyPoints: ["直角 ＝ 三角定規の かど", "紙を 2回 折ると 直角ができる", "かどに 直角を あてて たしかめる"],
    sections: [
      { heading: "1. 直角の 見つけ方", body: "■ 直角のつくり方\n① 紙を 半分に 折る\n② 折り目を そろえて もう 1回 折る\n③ できた かどが **直角**\n\n■ 直角の 見つけ方\n三角定規の 直角の かどを、図形の かどに あてます。ぴったり かさなれば 直角です。\n\n■ なぜ 折ると 直角に なるの？\n紙を 半分に 折った 折り目は 直線です。その 折り目を ぴったり かさねて もう 1回 折ると、折り目が たがいに まっすぐ 交わって 直角に なります。\n\n★ ここがポイント：**紙を 2回 折る**と 直角。かどは **三角定規**で たしかめる。", figureId: "u120e2_079_a" },
      { heading: "2. やってみよう", body: "【なにを きかれているかな】紙を 2回 折って できた かどは 何と いう 角？\n\n【なぜ この やりかたかな】折り目が ぴったり かさなって まっすぐ 交わるから。\n\n【ステップ1】紙を 半分に 折る\n【ステップ2】折り目を そろえて もう 1回 折る\n【ステップ3】角を 見る\n\n【こたえ】直角\n\n【たしかめ】三角定規の 直角を あてて ぴったりか 見る。" },
      { heading: "3. たしかめ（けんざん）の しかた", body: "■ やりかた その1\n折った 紙の かどに 三角定規の 直角を あてる。\n\n■ やりかた その2\n教室の 本の かどに 折った 紙の かどを あてる。\n\n★ ここがポイント：**べつの 方法**でも たしかめて、同じに なるか 見る。" },
      { heading: "4. よくある まちがい", body: "■ ■ 紙を ずらして 折って しまう\n折り目が そろっていないと 直角に ならない。\n\n■ なおしかた\n・折り目を ぴったり かさねて 折る\n・折ってから 三角定規で たしかめる\n\n★ ここがポイント：まちがえやすい ところを **先に 知って**おく。" },
      { heading: "5. じぶんの ことばで いってみよう", body: "■ ことばに して みよう（アウトプット）\n・紙を 2回 折って 直角を つくり、身の まわりの かどに あててみよう\n・直角の つくり方を おうちの 人に 説明してみよう\n\n■ おうちの人へ\n身近な かど（本・ドア・つくえ）に 折った 紙の 直角を あてて みる 遊びを しましょう。\n\n★ ここがポイント：**読むだけでなく、声に出して言う・紙に書く**と、しっかり身につきます。まちがえても大丈夫。「どうしてそう思ったの？」と聞いてあげてください。" },
    ],
    trapExamples: [{ question: "紙を 2回 折って できる かどは？", wrongAnswer: "三角形", trapExplanation: "角の 名前を 知らなかった。", correctAnswer: "直角", correctExplanation: "折り目を そろえて 2回 折ると 直角。" }],
