    trapExamples: [{ question: "辺が 3cm・5cm・3cm・5cm の 四角形（かどは 直角）は？", wrongAnswer: "正方形", trapExplanation: "辺の 長さを 見なかった。", correctAnswer: "長方形", correctExplanation: "辺が ぜんぶ 同じでは ないので 長方形。" }],
