    keyPoints: ["10が □こ で 数える", "50 ＝ 10が 5こ", "50＋30 ＝ 10が 8こ ＝ 80"],
    sections: [
      { heading: "1. 10の まとまりで 数える", body: "■ 10の まとまり\n・50 ＝ 10が **5こ**\n・30 ＝ 10が **3こ**\n・合わせて 10が **8こ** ＝ **80**\n\n■ なぜ 10の まとまり？\n10ずつの かたまりで 考えると、「5こ＋3こ＝8こ」という 1年生の 計算に なります。それを 10ばいするだけです。\n\n■ ほかの 例\n40＋20 → 10が 4こ ＋ 10が 2こ ＝ 10が 6こ ＝ 60。\n\n★ ここがポイント：**10が □こ**で 考えて、□の 計算を して **10ばい**する。", figureId: "u120e2_100_a" },
      { heading: "2. やってみよう", body: "【なにを きかれているかな】50＋30 を 10の まとまりで 計算しましょう。\n\n【なぜ この やりかたかな】10が 何こかを 数える と、1年生の 計算に なるから。\n\n【ステップ1】50 は 10が 5こ\n【ステップ2】30 は 10が 3こ\n【ステップ3】5こ＋3こ＝8こ → 80\n\n【こたえ】80\n\n【たしかめ】80−30＝50 で たしかめる。" },
      { heading: "3. たしかめ（けんざん）の しかた", body: "■ やりかた その1\nひき算で たしかめる。80−30＝50。\n\n■ やりかた その2\nひっ算でも たしかめる。0＋0＝0、5＋3＝8 で 80。\n\n★ ここがポイント：**べつの 方法**でも たしかめて、同じに なるか 見る。" },
      { heading: "4. よくある まちがい", body: "■ ■ 0を つけわすれる\n5＋3＝8 と して 8 と 答える。\n\n■ なおしかた\n・10が □こ なので □の 後ろに 0を つける\n・答えが 2けたに なって いるか 見る\n\n★ ここがポイント：まちがえやすい ところを **先に 知って**おく。" },
      { heading: "5. じぶんの ことばで いってみよう", body: "■ ことばに して みよう（アウトプット）\n・30＋40 を 10の まとまりで 計算してみよう\n・10の まとまりで 数える 方法を おうちの 人に 説明してみよう\n\n■ おうちの人へ\n10円玉を 使って「10が 何こ」で 数える 遊びを しましょう。\n\n★ ここがポイント：**読むだけでなく、声に出して言う・紙に書く**と、しっかり身につきます。まちがえても大丈夫。「どうしてそう思ったの？」と聞いてあげてください。" },
    ],
